<?php
require 'config/auth.php';require 'config/db.php';if(!has_permission('control.view')&&!has_permission('control.manage')){require_permission('control.view');}
$year=(int)($_GET['year']??fiscal_year_for_date());$unitId=(int)($_SESSION['user']['unit_id']??0);$isAdmin=($_SESSION['user']['role']??'')==='admin';
$sql="SELECT ca.*,u.unit_code,bt.budget_types,
COALESCE(SUM(CASE WHEN e.entry_type='increase' THEN e.amount ELSE 0 END),0) increase_amount,
COALESCE(SUM(CASE WHEN e.entry_type='transfer_out' THEN e.amount ELSE 0 END),0) transfer_amount,
COALESCE(SUM(CASE WHEN e.entry_type='return_army' THEN e.amount ELSE 0 END),0) return_amount,
COALESCE(SUM(CASE WHEN e.entry_type='carry' THEN e.amount ELSE 0 END),0) carry_amount,
COALESCE(SUM(CASE WHEN e.entry_type='request' THEN e.amount ELSE 0 END),0) request_amount,
COALESCE(SUM(CASE WHEN e.entry_type='obligation' THEN e.amount ELSE 0 END),0) obligation_amount,
COALESCE(SUM(CASE WHEN e.entry_type='payment' THEN e.amount ELSE 0 END),0) payment_amount,
COALESCE(SUM(CASE WHEN e.entry_type='remittance' THEN e.amount ELSE 0 END),0) remittance_amount
FROM control_accounts ca LEFT JOIN active_control_entries e ON e.control_account_id=ca.id LEFT JOIN units u ON u.id=ca.unit_id LEFT JOIN budget_transfers bt ON bt.id=ca.source_transfer_id WHERE ca.cancelled_at IS NULL AND ca.fiscal_year=?".($isAdmin?'':' AND ca.unit_id=?')." GROUP BY ca.id ORDER BY ca.id DESC";
$s=$conn->prepare($sql);$isAdmin?$s->bind_param('i',$year):$s->bind_param('ii',$year,$unitId);$s->execute();$rows=$s->get_result();
?>
<!DOCTYPE html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="UTF-8"><title>ผลการเบิกจ่าย</title><link rel="stylesheet" href="assets/css/style.css?v=<?= filemtime(__DIR__ . '/assets/css/style.css') ?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">แสดงผลการเบิกจ่าย</h1><p class="page-subtitle">สรุปงบจัดสรร การดำเนินงาน และยอดคงเหลือรายบัญชีคุม</p><form method="get" class="toolbar"><select name="year"><?php for($y=(int)date('Y')+541;$y<=(int)date('Y')+545;$y++):?><option value="<?=$y?>" <?=$y===$year?'selected':''?>><?=$y?></option><?php endfor;?></select><button class="btn btn-primary">แสดงผล</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th rowspan="2">ลำดับ</th><th rowspan="2">รหัสงบประมาณ / รายการ</th><th rowspan="2">ประเภทงบ</th><th colspan="3">งบประมาณจัดสรร</th><th colspan="4">การดำเนินงาน</th><th rowspan="2">นำส่ง</th><th rowspan="2">เบิกบัญชี GF</th><th rowspan="2">คงเหลือ</th><th rowspan="2">ร้อยละเบิกจ่าย GF</th></tr><tr><th>เพิ่มเดือนนี้</th><th>โอนไป</th><th>ส่งคืน ทบ.</th><th>กันไว้เบิก</th><th>ขอใช้</th><th>ผูกพัน</th><th>ตัดจ่าย</th></tr></thead><tbody><?php $n=0;while($r=$rows->fetch_assoc()):$n++;$base=(float)$r['received_amount'];$remaining=$base+(float)$r['increase_amount']-(float)$r['transfer_amount']-(float)$r['return_amount']-(float)$r['payment_amount']-(float)$r['remittance_amount'];$pct=$base>0?(float)$r['payment_amount']/$base*100:0;?><tr><td><?=$n?></td><td><a href="control_account_detail.php?id=<?=(int)$r['id']?>"><?=htmlspecialchars($r['budget_code'])?></a><div><?=htmlspecialchars($r['item_name'])?></div></td><td><?=htmlspecialchars((string)$r['budget_types'])?></td><?php foreach(['increase_amount','transfer_amount','return_amount','carry_amount','request_amount','obligation_amount','payment_amount','remittance_amount','payment_amount'] as $key):?><td class="text-right"><?=number_format((float)$r[$key],2)?></td><?php endforeach;?><td class="text-right"><b><?=number_format($remaining,2)?></b></td><td class="text-right"><?=number_format($pct,2)?>%</td></tr><?php endwhile;?><?php if(!$n):?><tr><td colspan="14" class="text-center">ไม่มีข้อมูล</td></tr><?php endif;?></tbody></table></div></section></main></body></html>

